import{_ as e,o as r,c as t,ag as i}from"./chunks/framework.DMXcdKmJ.js";const c=JSON.parse('{"title":"使用代码编辑器","description":"在应用开发中打开工程源码编辑器，保存修改、检查预览，并与 AI 协作而不覆盖他人文件。","frontmatter":{"title":"使用代码编辑器","description":"在应用开发中打开工程源码编辑器，保存修改、检查预览，并与 AI 协作而不覆盖他人文件。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/code-editor.md","filePath":"zh/使用指南/使用代码编辑器.md"}'),o={name:"zh/guide/code-editor.md"};function d(h,a,l,n,p,s){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="使用代码编辑器" tabindex="-1">使用代码编辑器 <a class="header-anchor" href="#使用代码编辑器" aria-label="Permalink to &quot;使用代码编辑器&quot;">​</a></h1><p>代码编辑器用于维护<strong>当前工程的源码</strong>。它与“资源”页的工程对象库不同，也不是修改平台服务器配置的入口。</p><p>开始前，先从“工程管理”打开 <strong>“应用开发”</strong>，完成模板初始化，等待开发环境就绪。</p><h2 id="_1-打开编辑器" tabindex="-1">1. 打开编辑器 <a class="header-anchor" href="#_1-打开编辑器" aria-label="Permalink to &quot;1. 打开编辑器&quot;">​</a></h2><p>点击工作区的 <strong>“编辑器”</strong>。出现“正在连接工程工作台”时先等待，不重复启动多个开发环境。</p><p>按钮不可用或显示尚未接入时，先检查开发环境状态；页面提供“重新连接”时按提示操作。仍失败则记录工程与错误，请管理员检查，不手工拼接服务地址。</p><p>编辑器采用浏览器中的源码工作台。文件和菜单的通用用法以编辑器当前界面为准，本页说明 InduFrame 的工程入口与协作边界，不要求在自己电脑另装一套平台。</p><h2 id="_2-查找并修改文件" tabindex="-1">2. 查找并修改文件 <a class="header-anchor" href="#_2-查找并修改文件" aria-label="Permalink to &quot;2. 查找并修改文件&quot;">​</a></h2><p>从文件区域打开要修改的工程文件。先确认文件路径和内容，再做一次较小的修改，并使用编辑器的保存操作。</p><p>不要把另一个工程的文件或整套模板直接覆盖进来。新手不确定文件用途时，可先让 <a href="/induframe-docs/zh/guide/ai-development.html">AI 助手</a>解释结构，再确认修改范围。</p><p>源码中的环境配置、口令和连接资料也应谨慎处理，不将真实凭据写入可共享或导出的文件。</p><h2 id="_3-与-ai-协同" tabindex="-1">3. 与 AI 协同 <a class="header-anchor" href="#_3-与-ai-协同" aria-label="Permalink to &quot;3. 与 AI 协同&quot;">​</a></h2><p>AI 和编辑器维护的是同一份工程源码，不是各自的草稿副本。</p><ul><li>手工修改前确认 AI 是否正在处理同一文件。</li><li>AI 完成后，重新核对相关文件和差异，不只看聊天回复。</li><li>编辑器提示文件在外部被修改时，先比较内容，再决定保留哪一份。</li><li>多人操作前协调任务范围，避免相互覆盖。</li></ul><p>停止 AI、删除对话或切换对话分支不会自动撤销代码。重要修改先做好适当备份，再尝试大范围重写。</p><h2 id="_4-保存后检查页面" tabindex="-1">4. 保存后检查页面 <a class="header-anchor" href="#_4-保存后检查页面" aria-label="Permalink to &quot;4. 保存后检查页面&quot;">​</a></h2><p>切换到 <strong>“页面”</strong>，等待或刷新开发预览，核对画面、交互和数据权限。页面没有更新时，先确认文件已保存，再按<a href="/induframe-docs/zh/guide/preview.html">预览说明</a>区分刷新与重启。</p><p>编辑器可打开只说明源码服务能访问，不表示预览、数据服务和正式部署都已经正常。代码保存也不会自动更新已部署版本。</p><h2 id="_5-结束本次操作" tabindex="-1">5. 结束本次操作 <a class="header-anchor" href="#_5-结束本次操作" aria-label="Permalink to &quot;5. 结束本次操作&quot;">​</a></h2><p>先保存文件，再关闭工作区。需要停止整个开发环境时，通知共同使用者后按<a href="/induframe-docs/zh/guide/workspace.html">工作区说明</a>确认；AI、编辑器和预览都会暂停。</p><p>出现保存失败、文件冲突或连接中断时，保留未保存内容和具体提示，确认实际保存结果，不通过删除工程、关闭浏览器安全功能或共享登录资料处理。</p><p>下一步：<a href="/induframe-docs/zh/guide/preview.html">页面预览</a> · <a href="/induframe-docs/zh/guide/project-files.html">对象存储管理</a>。</p>',22)])])}const u=e(o,[["render",d]]);export{c as __pageData,u as default};
